function Get-TestProduct {
    <#
    .SYNOPSIS
    Returns the taxonomy key of the Microsoft product a test is about: its Product when it names one, otherwise the
    product its pillar or service stands for. Returns nothing for a product Maester does not know.
    #>
    param([AllowNull()] $Product, [AllowNull()] [object[]] $Service, [AllowNull()] [object[]] $Pillar)
    if ($Product -is [string] -and $Product) {
        $key = $script:ProductAliases[$Product.Trim().ToLowerInvariant()]
        if ($key) { return $key }
    }
    $services = @($Service | Where-Object { $_ -is [string] })
    if ($services -contains 'Graph' -or -not $services) {
        foreach ($p in @($Pillar | Where-Object { $_ -is [string] })) { if ($script:PillarProducts[$p]) { return $script:PillarProducts[$p] } }
    }
    foreach ($s in $services) { if ($script:ServiceProducts[$s]) { return $script:ServiceProducts[$s] } }
}

function Read-PackCatalog {
    <#
    .SYNOPSIS
    Reads the tests a pack lists in its Catalog file, for the site only: nothing in it is run.

    .DESCRIPTION
    The catalog is JSON with a Tests array, such as the Zero Trust Assessment pack's catalog.json. Only entries whose
    Id belongs to the pack (<Code>. for a built-in pack, MP.<Code>. otherwise) are kept, at most 2,000, and the file may
    be at most 2 MB. Text is cleaned like every other field a pack supplies.
    #>
    param([string] $Root, $Manifest)
    if (-not $Manifest.PSObject.Properties['Catalog'] -or $Manifest.Catalog -isnot [string] -or -not $Manifest.Code) { return }
    $path = $Manifest.Catalog
    if ($path -match '(^|[\\/])\.\.([\\/]|$)' -or [System.IO.Path]::IsPathRooted($path) -or $path -notmatch '\.json$') { return }
    $file = Get-Item -LiteralPath (Join-Path $Root $path) -ErrorAction SilentlyContinue
    if (-not $file -or $file.PSIsContainer -or $file.LinkType -or $file.Length -gt 2MB) { return }
    $data = try { Get-Content -LiteralPath $file.FullName -Raw | ConvertFrom-Json -ErrorAction Stop } catch { $null }
    if (-not $data -or -not $data.PSObject.Properties['Tests']) { return }
    $code = [regex]::Escape([string]$Manifest.Code)
    $pattern = "^(MP\.)?$code\.[A-Za-z0-9._-]{1,40}$"
    $severities = 'Critical', 'High', 'Medium', 'Low', 'Info'
    $words = { param($v, $max) @($v | Where-Object { $_ -is [string] -and $_ -match '^[A-Za-z0-9 .&+/-]{1,40}$' } | Select-Object -First $max) }
    $seen = @{}
    foreach ($t in @($data.Tests | Select-Object -First 2000)) {
        if ($t -isnot [pscustomobject] -or $t.Id -isnot [string] -or $t.Id -notmatch $pattern -or $seen[$t.Id]) { continue }
        $seen[$t.Id] = $true
        $service = @(& $words $t.Service 5)
        $pillar = @(& $words $t.Pillar 5)
        $product = if ($t.PSObject.Properties['Product']) { $t.Product } else { $null }
        [ordered]@{
            Id             = $t.Id
            Title          = ConvertTo-SafeText ([string]$t.Title) 200
            Severity       = if ($t.Severity -in $severities) { [string]$t.Severity } else { $null }
            Service        = $service
            Suite          = $null
            LongRunning    = $false
            Markdown       = $null
            Product        = @(Get-TestProduct -Product $product -Service $service -Pillar $pillar)
            RelatedProduct = @()
            Pillar         = $pillar
            Category       = if ($t.Category -is [string]) { ConvertTo-SafeText $t.Category 60 } else { $null }
            Catalog        = $true
        }
    }
}

