function Get-MtScubaGogglesInstance {
    <#
    .SYNOPSIS
    Returns one SCUBA.GWS instance per policy result in a ScubaGoggles ScubaResults file.

    .DESCRIPTION
    Instance source of the SCUBA.GWS family. Reads the ScubaResults JSON that the scubagoggles gws command wrote,
    from the ScubaGoggles.ReportPath setting, and returns one instance per result. Skips the whole family, with
    the reason, when the setting is empty, the file is not found or the report is too old.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param()

    $reportPath = [string](Get-MtSetting -Name 'ScubaGoggles.ReportPath' -Default '')
    if ([string]::IsNullOrWhiteSpace($reportPath)) {
        Add-MtTestResultDetail -SkippedBecause Custom -SkippedCustomReason 'No ScubaGoggles report to read. Run scubagoggles gws, then set the ScubaGoggles.ReportPath setting to the ScubaResults file or the folder it wrote.'
    }

    $file = Resolve-MtScubaGogglesResultFile -Path $reportPath
    $report = Get-Content -LiteralPath $file -Raw -Encoding utf8 | ConvertFrom-Json -Depth 20
    if (-not $report.PSObject.Properties['Results'] -or -not $report.PSObject.Properties['MetaData']) {
        throw "$file is not a ScubaGoggles results file: it has no MetaData or Results."
    }
    if ([string]$report.MetaData.Tool -ne 'ScubaGoggles') {
        Add-MtTestResultDetail -SkippedBecause Custom -SkippedCustomReason "$file was written by $($report.MetaData.Tool), not ScubaGoggles."
    }

    $maxAgeDays = [int](Get-MtSetting -Name 'ScubaGoggles.MaxReportAgeDays' -Default 7)
    # ConvertFrom-Json reads the ISO date as a DateTime already; text is parsed invariantly, never in the current culture.
    $written = [datetime]::MinValue
    $hasDate = if ($report.MetaData.TimestampZulu -is [datetime]) { $written = $report.MetaData.TimestampZulu; $true }
    else {
        [datetime]::TryParse([string]$report.MetaData.TimestampZulu, [cultureinfo]::InvariantCulture,
            [System.Globalization.DateTimeStyles]::AdjustToUniversal -bor [System.Globalization.DateTimeStyles]::AssumeUniversal, [ref]$written)
    }
    if ($maxAgeDays -gt 0 -and $hasDate -and $written.ToUniversalTime() -lt [datetime]::UtcNow.AddDays(-$maxAgeDays)) {
        Add-MtTestResultDetail -SkippedBecause Custom -SkippedCustomReason "The ScubaGoggles report at $file was written on $($written.ToString('yyyy-MM-dd')), more than $maxAgeDays days ago. Run scubagoggles gws again, or raise the ScubaGoggles.MaxReportAgeDays setting."
    }

    ConvertTo-MtScubaGogglesInstance -Report $report -Catalog (Get-MtScubaGogglesCatalog)
}

function Resolve-MtScubaGogglesResultFile {
    <#
    .SYNOPSIS
    Returns the ScubaResults file at Path: the file itself, the newest in the folder, or the newest in a folder in it.

    .DESCRIPTION
    scubagoggles gws writes ScubaResults_<uuid>.json in a new GWSBaselineConformance_<time> folder under its output
    path on every run, so Path can be the file, that run's folder, or the output path, where the newest run wins.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)] [string] $Path
    )

    if (Test-Path -LiteralPath $Path -PathType Leaf) { return (Resolve-Path -LiteralPath $Path).ProviderPath }
    $file = $null
    if (Test-Path -LiteralPath $Path -PathType Container) {
        $file = @(Get-ChildItem -LiteralPath $Path -Filter 'ScubaResults*.json' -File) | Sort-Object -Property LastWriteTimeUtc -Descending | Select-Object -First 1
        if (-not $file) {
            $file = @(Get-ChildItem -LiteralPath $Path -Directory | ForEach-Object { Get-ChildItem -LiteralPath $_.FullName -Filter 'ScubaResults*.json' -File }) |
                Sort-Object -Property LastWriteTimeUtc -Descending | Select-Object -First 1
        }
    }
    if (-not $file) {
        Add-MtTestResultDetail -SkippedBecause Custom -SkippedCustomReason "No ScubaGoggles results file was found at $Path. Point the ScubaGoggles.ReportPath setting at a ScubaResults_<uuid>.json file, the folder scubagoggles gws wrote it in, or its output folder."
    }
    $file.FullName
}

function Get-MtScubaGogglesCatalog {
    <#
    .SYNOPSIS
    Returns the pack's catalog of ScubaGoggles policies, by control ID without its version (GWS.GMAIL.1.1).
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param()

    $catalog = @{}
    $path = Join-Path -Path $PSScriptRoot -ChildPath '..' -AdditionalChildPath 'catalog.json'
    if (Test-Path -LiteralPath $path) {
        foreach ($entry in @((Get-Content -LiteralPath $path -Raw -Encoding utf8 | ConvertFrom-Json).Tests)) {
            $catalog[([string]$entry.ControlId -replace 'v\d+$', '')] = $entry
        }
    }
    $catalog
}

function ConvertTo-MtScubaGogglesInstance {
    <#
    .SYNOPSIS
    Turns the Results of a ScubaGoggles report into SCUBA.GWS instances.

    .DESCRIPTION
    The instance suffix is the control ID without GWS. and its version (GMAIL.1.1 for GWS.GMAIL.1.1v1), so a row
    keeps its ID when CISA moves a policy to a new version. A control that ScubaGoggles reports more than once gets
    -2, -3 and so on, in report order. Each instance carries the report's row, its group and the policy's catalog
    entry, and the severity of its criticality: SHALL is High, SHOULD Medium and MAY Low.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        # A ScubaGoggles report, read from its ScubaResults JSON.
        [Parameter(Mandatory)] $Report,

        # The pack's catalog, from Get-MtScubaGogglesCatalog.
        [Parameter()] [hashtable] $Catalog = @{}
    )

    $severity = @{ shall = 'High'; should = 'Medium'; may = 'Low' }
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($product in $Report.Results.PSObject.Properties) {
        foreach ($group in @($product.Value)) {
            foreach ($row in @($group.Controls)) {
                $controlId = [string]$row.'Control ID'
                $policy = $controlId -replace 'v\d+$', ''
                $id = ($policy -replace '^GWS\.', '' -replace '[^A-Za-z0-9._-]', '_') -replace '^[^A-Za-z0-9]+', ''
                if (-not $id) { continue }
                $unique = $id
                for ($n = 2; -not $seen.Add($unique); $n++) { $unique = "$id-$n" }
                $entry = $Catalog[$policy]
                $title = if ($entry) { [string]$entry.Title } else { ConvertFrom-MtScubaGogglesHtml -Html ([string]$row.Requirement) }
                $tags = @('ScubaGoggles', ($policy -replace '\.\d+\.\d+$', ''))
                if ($entry -and @($entry.Indicators) -contains 'BOD 25-01 Requirement') { $tags += 'BOD-25-01' }
                $instance = [ordered]@{
                    Id    = $unique
                    Title = ($title -replace '\s+', ' ').Trim()
                    Tag   = $tags
                    Data  = [pscustomobject]@{ Row = $row; Group = $group; Policy = $entry; Product = $product.Name }
                }
                $level = ([string]$row.Criticality -split '/')[0].Trim().ToLowerInvariant()
                if ($severity.ContainsKey($level)) { $instance.Severity = $severity[$level] }
                [pscustomobject]$instance
            }
        }
    }
}

function ConvertFrom-MtScubaGogglesHtml {
    <#
    .SYNOPSIS
    Turns the HTML that ScubaGoggles writes in a result's Requirement and Details into Markdown.

    .DESCRIPTION
    ScubaGoggles writes its details for its own HTML report: definition lists of organisational units, line
    breaks, lists and links. They become Markdown, and every other tag is removed, so nothing from the report is
    shown as HTML in the Maester report. The indicator badges after a requirement are left out.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter()] [AllowEmptyString()] [string] $Html
    )

    if ([string]::IsNullOrWhiteSpace($Html)) { return '' }
    $text = $Html -replace '(?s)<div class="badges">.*?</div>', ''
    $text = $text -replace '(?is)<a\s[^>]*href="(https?://[^"]+)"[^>]*>(.*?)</a>', '[$2]($1)'
    $text = $text -replace '(?is)<dt>(.*?)</dt>\s*<dd>(.*?)</dd>', '**$1**: $2'
    $text = $text -replace '(?i)<br\s*/?>', "`n"
    $text = $text -replace '(?i)<li[^>]*>', "`n- "
    $text = $text -replace '(?i)</?(b|strong)>', '**'
    $text = $text -replace '(?i)</?(i|em)>', '_'
    $text = $text -replace '<[^>]+>', ''
    $text = [System.Net.WebUtility]::HtmlDecode($text)
    # A list item that ScubaGoggles starts on its own line ("- " then the text on the next) is one line.
    $text = $text -replace '(?m)^(\s*)-\s*\n\s+', '$1- '
    $text = $text -replace '(?m)[ \t]+$', ''
    ($text -replace '\n{3,}', "`n`n").Trim()
}

function Get-MtScubaGogglesDescription {
    <#
    .SYNOPSIS
    Writes the Markdown description of one policy: its rationale, note, how to configure it and its mappings.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory)] [string] $ControlId,
        [Parameter()] [string] $Criticality,
        [Parameter()] [string] $Product,
        [Parameter()] $Group,
        [Parameter()] $Policy
    )

    $groupName = if ($Policy) { [string]$Policy.Group } elseif ($Group) { [string]$Group.GroupName } else { '' }
    $where = @($Product, $groupName) | Where-Object { $_ }
    $lines = [System.Collections.Generic.List[string]]::new()
    $lines.Add("**$ControlId** ($($Criticality.ToUpperInvariant())) · $($where -join ' › ')")
    if ($Policy -and $Policy.Rationale) { $lines.Add(''); $lines.Add([string]$Policy.Rationale) }
    if ($Policy -and $Policy.Note) { $lines.Add(''); $lines.Add("_Note:_ $($Policy.Note)") }
    if ($Policy -and $Policy.Remediation) {
        $lines.Add(''); $lines.Add('#### Remediation'); $lines.Add(''); $lines.Add([string]$Policy.Remediation)
    }
    $links = [System.Collections.Generic.List[string]]::new()
    $url = if ($Policy -and $Policy.Url) { [string]$Policy.Url } elseif ($Group -and $Group.GroupReferenceURL) { [string]$Group.GroupReferenceURL } else { $null }
    if ($url) { $links.Add("[CISA baseline]($url)") }
    if ($Policy -and @($Policy.Nist).Count) { $links.Add("NIST SP 800-53: $(@($Policy.Nist) -join ', ')") }
    if ($Policy -and @($Policy.Mitre).Count) { $links.Add("MITRE ATT&CK: $(@($Policy.Mitre) -join ', ')") }
    if ($links.Count) { $lines.Add(''); $lines.Add($links -join ' · ') }
    $lines -join "`n"
}

function Test-MtScubaGoggles {
    [MaesterTest(
        Id = 'SCUBA.GWS',
        Title = 'CISA ScubaGoggles for Google Workspace',
        Product = 'Google Workspace',
        InstanceSource = 'Get-MtScubaGogglesInstance',
        Tag = 'ScubaGoggles',
        Author = 'merill',
        HelpUrl = 'https://github.com/cisagov/ScubaGoggles'
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # One result of a ScubaGoggles report, supplied by the engine.
        $Instance
    )

    $row = $Instance.Data.Row
    $description = Get-MtScubaGogglesDescription -ControlId ([string]$row.'Control ID') -Criticality ([string]$row.Criticality) `
        -Product $(if ($Instance.Data.Policy) { [string]$Instance.Data.Policy.Product } else { [string]$Instance.Data.Product }) `
        -Group $Instance.Data.Group -Policy $Instance.Data.Policy
    $details = ConvertFrom-MtScubaGogglesHtml -Html ([string]$row.Details)
    $detail = @{ Description = $description; Result = $details }

    switch -Regex ([string]$row.Result) {
        '^Pass$' {
            Add-MtTestResultDetail @detail
            return $true
        }
        '^(Fail|Warning)$' {
            # Warning is a SHOULD or MAY policy that is not met; the instance's severity says how much it matters.
            Add-MtTestResultDetail @detail
            return $false
        }
        '^No events found$' {
            # A log-based check found no event that shows the setting, so its state is unknown.
            Add-MtTestResultDetail @detail -Investigate
            return $true
        }
        '^N/A$' {
            $reason = if ($details) { $details } else { 'ScubaGoggles cannot check this policy automatically. Check it by hand.' }
            Add-MtTestResultDetail -Description $description -SkippedBecause Custom -SkippedCustomReason $reason
        }
        '^Omitted$' {
            Add-MtTestResultDetail -Description $description -SkippedBecause Custom -SkippedCustomReason "Omitted in the ScubaGoggles config. $details".Trim()
        }
        '^Incorrect result$' {
            Add-MtTestResultDetail -Description $description -SkippedBecause Custom -SkippedCustomReason "Marked as an incorrect result in the ScubaGoggles config. ScubaGoggles reported $($row.OriginalResult). $details".Trim()
        }
        default {
            # Error, Error - Test results missing, or a result this version of the pack does not know.
            Add-MtTestResultDetail @detail -SkippedBecause Error
        }
    }
}

