Describe 'ScubaGoggles pack' {
    BeforeAll {
        Import-Module $PSScriptRoot/../../Maester.psd1 -Force -WarningAction SilentlyContinue
        $script:PackRoot = (Resolve-Path "$PSScriptRoot/../../../packs/scubagoggles").Path
        $script:TestsPath = Join-Path $script:PackRoot 'tests'
        $script:Fixture = (Resolve-Path "$PSScriptRoot/../fixtures/scubagoggles").Path
        $script:FixtureFile = @(Get-ChildItem -LiteralPath $script:Fixture -Filter 'ScubaResults*.json' -File -Recurse)[0].FullName

        # The fixture is a cut of ScubaGoggles' own sample report, without its raw export: the first two rows of
        # each result it has, and the results the sample lacks (Omitted, Incorrect result, Error and a policy
        # reported twice) written on Gmail policies.
        function Invoke-ScubaPack {
            param([hashtable] $Setting = @{})
            $globalSettings = @{ 'ScubaGoggles.ReportPath' = $script:Fixture; 'ScubaGoggles.MaxReportAgeDays' = 0 }
            foreach ($key in $Setting.Keys) { $globalSettings[$key] = $Setting[$key] }
            $config = [pscustomobject]@{
                GlobalSettings = [pscustomobject]$globalSettings
                Environment    = [pscustomobject]@{ Enforce = [pscustomobject]@{ Service = $false } }
            }
            @(Invoke-MtTest -Path $script:TestsPath -Id SCUBA.GWS -Config $config)
        }

        $script:Rows = Invoke-ScubaPack
    }

    Context 'the pack files' {
        It 'is a valid pack' {
            $pack = Test-MtPack -Path $script:PackRoot -Official
            $pack.IsValid | Should -BeTrue
            $pack.Errors | Should -BeNullOrEmpty
            $pack.TestIds | Should -Be @('SCUBA.GWS')
        }

        It 'has a valid native test' {
            $test = Get-MtTest -Path (Join-Path $script:TestsPath 'Test.SCUBA.GWS.ps1')
            $test.IsValid | Should -BeTrue
            $test.Errors | Should -BeNullOrEmpty
            $test.InstanceSource | Should -Be 'Get-MtScubaGogglesInstance'
            $test.Suite | Should -Be 'SCUBA.GWS'
        }

        It 'is off by default' {
            $manifest = Get-Content (Join-Path $script:PackRoot 'maester-pack.json') -Raw | ConvertFrom-Json
            $manifest.Id | Should -Be 'maester.scubagoggles'
            $manifest.Code | Should -Be 'SCUBA.GWS'
            $manifest.EnabledByDefault | Should -BeFalse
        }

        It 'has a catalog of unique policy IDs with their text' {
            $catalog = Get-Content (Join-Path $script:PackRoot 'catalog.json') -Raw | ConvertFrom-Json
            $catalog.Version | Should -Not -BeNullOrEmpty
            $catalog.Tests.Count | Should -BeGreaterThan 0
            @($catalog.Tests.Id | Where-Object { $_ -notmatch '^SCUBA\.GWS\.[A-Z]+\.\d+\.\d+$' }) | Should -BeNullOrEmpty
            @($catalog.Tests.Id | Sort-Object -Unique).Count | Should -Be $catalog.Tests.Count
            @($catalog.Tests | Where-Object { -not $_.Title -or -not $_.Rationale -or -not $_.Remediation -or $_.Criticality -notin 'SHALL', 'SHOULD', 'MAY' }) | Should -BeNullOrEmpty
        }
    }

    Context 'reading a report' {
        It 'writes one row per result' {
            $script:Rows.Count | Should -Be 13
            @($script:Rows | Where-Object ParentId -ne 'SCUBA.GWS') | Should -BeNullOrEmpty
        }

        It 'maps <Id> to <Result>' -ForEach @(
            @{ Id = 'SCUBA.GWS.ASSUREDCONTROLS.1.1'; Result = 'Passed' }
            @{ Id = 'SCUBA.GWS.CALENDAR.1.1'; Result = 'Failed' }
            @{ Id = 'SCUBA.GWS.ASSUREDCONTROLS.2.1'; Result = 'Failed' }
            @{ Id = 'SCUBA.GWS.COMMONCONTROLS.2.1'; Result = 'Investigate' }
            @{ Id = 'SCUBA.GWS.CALENDAR.3.2'; Result = 'Skipped' }
            @{ Id = 'SCUBA.GWS.GMAIL.4.1'; Result = 'Skipped' }
            @{ Id = 'SCUBA.GWS.GMAIL.4.2'; Result = 'Skipped' }
            @{ Id = 'SCUBA.GWS.GMAIL.4.3'; Result = 'Error' }
            @{ Id = 'SCUBA.GWS.GMAIL.4.4'; Result = 'Error' }
        ) {
            ($script:Rows | Where-Object Id -eq $Id).Result | Should -Be $Result
        }

        It 'gives a SHALL policy High severity and a SHOULD policy Medium' {
            ($script:Rows | Where-Object Id -eq 'SCUBA.GWS.CALENDAR.1.1').Severity | Should -Be 'High'
            ($script:Rows | Where-Object Id -eq 'SCUBA.GWS.ASSUREDCONTROLS.2.1').Severity | Should -Be 'Medium'
        }

        It 'describes the policy from the catalog and shows the details as Markdown' {
            $row = $script:Rows | Where-Object Id -eq 'SCUBA.GWS.ASSUREDCONTROLS.2.1'
            $row.Title | Should -Be 'Data processing across multiple regions SHOULD be disabled for all Google Workspace products.'
            $row.Tag | Should -Contain 'GWS.ASSUREDCONTROLS'
            $row.ResultDetail.TestDescription | Should -BeLike '`*`*GWS.ASSUREDCONTROLS.2.1v1`*`* (SHOULD)*'
            $row.ResultDetail.TestDescription | Should -BeLike '*#### Remediation*'
            $row.ResultDetail.TestResult | Should -BeLike '*- `*`*Cool Example Org`*`*: *'
            $row.ResultDetail.TestResult | Should -Not -Match '<[a-z]'
        }

        It 'keeps the reasons ScubaGoggles gives for what it does not check' {
            ($script:Rows | Where-Object Id -eq 'SCUBA.GWS.CALENDAR.3.2').ReasonDetail | Should -BeLike '*manually check*'
            ($script:Rows | Where-Object Id -eq 'SCUBA.GWS.GMAIL.4.1').ReasonDetail | Should -BeLike 'Omitted in the ScubaGoggles config.*another team*'
            ($script:Rows | Where-Object Id -eq 'SCUBA.GWS.GMAIL.4.2').ReasonDetail | Should -BeLike '*ScubaGoggles reported Fail*'
        }

        It 'numbers a policy that ScubaGoggles reports twice' {
            ($script:Rows | Where-Object Id -eq 'SCUBA.GWS.GMAIL.4.4-2').Result | Should -Be 'Passed'
        }

        It 'reads the report from the file, its run folder or the output folder' {
            (Invoke-ScubaPack -Setting @{ 'ScubaGoggles.ReportPath' = $script:FixtureFile }).Count | Should -Be 13
            (Invoke-ScubaPack -Setting @{ 'ScubaGoggles.ReportPath' = (Split-Path -Parent $script:FixtureFile) }).Count | Should -Be 13
        }

        It 'skips the family when no report is set' {
            $rows = Invoke-ScubaPack -Setting @{ 'ScubaGoggles.ReportPath' = '' }
            $rows.Count | Should -Be 1
            $rows[0].Result | Should -Be 'Skipped'
            $rows[0].ReasonDetail | Should -BeLike '*Run scubagoggles gws*'
        }

        It 'skips the family when the report is missing' {
            $rows = Invoke-ScubaPack -Setting @{ 'ScubaGoggles.ReportPath' = (Join-Path $TestDrive 'none') }
            $rows.Count | Should -Be 1
            $rows[0].Result | Should -Be 'Skipped'
            $rows[0].ReasonDetail | Should -BeLike '*No ScubaGoggles results file was found*'
        }

        It 'skips the family when the report is too old' {
            $rows = Invoke-ScubaPack -Setting @{ 'ScubaGoggles.MaxReportAgeDays' = 7 }
            $rows.Count | Should -Be 1
            $rows[0].Result | Should -Be 'Skipped'
            $rows[0].ReasonDetail | Should -BeLike '*written on 2026-10-15, more than 7 days ago*'
        }

        It 'skips the family for a report another SCuBA tool wrote' {
            $report = Get-Content -LiteralPath $script:FixtureFile -Raw | ConvertFrom-Json
            $report.MetaData.Tool = 'ScubaGear'
            $file = Join-Path $TestDrive 'ScubaResults_gear.json'
            $report | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $file -Encoding utf8
            $rows = Invoke-ScubaPack -Setting @{ 'ScubaGoggles.ReportPath' = $file }
            $rows.Count | Should -Be 1
            $rows[0].ReasonDetail | Should -BeLike '*written by ScubaGear, not ScubaGoggles*'
        }
    }
}

